--- a//home/xyconix11x/Ayid/xyconix11x/Skripsi/Daedalus/ayid/landing.html
+++ b//home/xyconix11x/Ayid/xyconix11x/Skripsi/Daedalus/ayid/landing.html
@@ +124 -0 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8" />
+  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
+  <title>Ayid — Landing Page</title>
+  <meta name="description" content="Ayid landing page" />
+  <style>
+    :root {
+      --bg: #0f0f13;
+      --card: #1a1a22;
+      --accent: #5c7cfa;
+      --text: #e6e6e9;
+      --muted: #9a9ab3;
+    }
+    * { box-sizing: border-box; margin: 0; padding: 0; }
+    body {
+      font-family: "Inter", system-ui, sans-serif;
+      background: var(--bg);
+      color: var(--text);
+      line-height: 1.6;
+    }
+    header {
+      padding: 1.5rem 3rem;
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      border-bottom: 1px solid #2a2a33;
+    }
+    header h1 { font-size: 1.5rem; font-weight: 700; }
+    header nav a { color: var(--muted); text-decoration: none; margin-left: 1.5rem; font-size: .9rem; }
+    header nav a:hover { color: var(--text); }
+    .hero {
+      text-align: center;
+      padding: 5rem 1.5rem;
+      background: linear-gradient(160deg, #1a1a22 0%, #0f0f13 100%);
+    }
+    .hero h2 { font-size: 3rem; font-weight: 800; margin-bottom: 1.5rem; }
+    .hero p { font-size: 1.25rem; color: var(--muted); max-width: 640px; margin: 0 auto 2.5rem; }
+    .hero .cta {
+      display: inline-block;
+      background: var(--accent);
+      color: #fff;
+      border: none;
+      padding: .9rem 2.2rem;
+      font-size: 1rem;
+      border-radius: .5rem;
+      cursor: pointer;
+      font-weight: 600;
+      transition: opacity .2s;
+    }
+    .hero .cta:hover { opacity: .85; }
+    section { padding: 4rem 2rem; max-width: 1000px; margin: 0 auto; }
+    section h3 { font-size: 2rem; margin-bottom: 1.5rem; text-align: center; }
+    .features { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.5rem; }
+    .card {
+      background: var(--card);
+      border: 1px solid #2a2a33;
+      border-radius: .75rem;
+      padding: 2rem;
+      text-align: center;
+      transition: transform .2s, border-color .2s;
+    }
+    .card:hover { transform: translateY(-4px); border-color: var(--accent); }
+    .card h4 { font-size: 1.2rem; margin-bottom: .75rem; }
+    .card p { color: var(--muted); font-size: .95rem; }
+    footer {
+      text-align: center;
+      padding: 2.5rem;
+      color: var(--muted);
+      font-size: .9rem;
+      border-top: 1px solid #2a2a33;
+    }
+  </style>
+</head>
+<body>
+
+  <header>
+    <h1>Ayid</h1>
+    <nav>
+      <a href="#features">Features</a>
+      <a href="#about">About</a>
+      <a href="#contact">Contact</a>
+    </nav>
+  </header>
+
+  <section class="hero">
+    <h2>Built for the next generation of developers</h2>
+    <p>Streamline your workflow, collaborate smarter, and ship faster with Ayid — the all-in-one platform for modern teams.</p>
+    <button class="cta">Get Started</button>
+  </section>
+
+  <section id="features">
+    <h3>Features</h3>
+    <div class="features">
+      <div class="card">
+        <h4>Smart Collaboration</h4>
+        <p>Collaborate in real-time with your team using shared workspaces and intelligent suggestions.</p>
+      </div>
+      <div class="card">
+        <h4>Lightning Fast</h4>
+        <p>Optimized for speed so you can iterate, test, and deploy without friction.</p>
+      </div>
+      <div class="card">
+        <h4>Secure by Default</h4>
+        <p>End-to-end encryption and enterprise-grade security built into every layer.</p>
+      </div>
+    </div>
+  </section>
+
+  <section id="about">
+    <h3>About</h3>
+    <p style="max-width:720px;margin:0 auto;text-align:center;color:var(--muted);">
+      Ayid is designed to empower developers and teams to build ambitious products with less friction.
+      Our mission is to remove the repetitive and let you focus on what matters — creating.
+    </p>
+  </section>
+
+  <footer id="contact">
+    <p>© 2025 Ayid. All rights reserved.</p>
+  </footer>
+
+</body>
+</html>
